// ============================================================================
// Config & Safety Gate
// Env-only configuration with fail-safe flags, reconciliation-period
// resolution, and webhook authentication (secret checked here, then the
// header and query string are stripped from item data).
//
//   * Safe-ON  (SANDBOX_MODE, DRY_RUN, BLOCK_EXPORT_ON_PENDING_REVIEW) turn OFF
//     only on an explicit false/0/no/off.
//   * Safe-OFF (CSV_EXPORT_ENABLED, HUBSPOT_MUTATIONS_ENABLED, ...) turn ON only
//     on an explicit true/1/yes/on. Typos keep the safe value.
//   * Blocked $env access => all safe defaults.
// ============================================================================
const TRUTHY = ['true', '1', 'yes', 'on'];
const FALSY = ['false', '0', 'no', 'off'];
let envBlocked = false;
function readEnv(key) {
  try {
    const v = $env[key];
    return v === undefined || v === null ? '' : String(v).trim();
  } catch (e) {
    envBlocked = true;
    return '';
  }
}
const str = (k, d = '') => readEnv(k) || d;
const safeOn = (k) => !FALSY.includes(readEnv(k).toLowerCase());
const safeOff = (k) => TRUTHY.includes(readEnv(k).toLowerCase());
const list = (k, d = '') => (readEnv(k) || d).split(',').map((s) => s.trim()).filter(Boolean);
const prop = (k, d) => (readEnv(k) || d).replace(/[^a-z0-9_]/gi, '');
const DECIMAL_RE = /^\d+(\.\d+)?$/;
const configErrors = [];
const warnings = [];
const intIn = (k, d, min, max) => {
  const raw = readEnv(k);
  if (raw === '') return d;
  const n = Number(raw);
  if (!Number.isInteger(n) || n < min || n > max) { configErrors.push(`${k} must be an integer between ${min} and ${max} (got "${raw}")`); return d; }
  return n;
};
const decIn = (k, d) => {
  const raw = readEnv(k).replace(/[,_\s]/g, '');
  if (raw === '') return d;
  if (!DECIMAL_RE.test(raw)) { configErrors.push(`${k} must be a non-negative decimal (got "${readEnv(k)}")`); return d; }
  return raw;
};

const sandboxMode = safeOn('SANDBOX_MODE');
const dryRun = safeOn('DRY_RUN');
const csvExportEnabled = safeOff('CSV_EXPORT_ENABLED');
const hubspotMutationsEnabled = safeOff('HUBSPOT_MUTATIONS_ENABLED');
const hasHubspotToken = readEnv('HUBSPOT_ACCESS_TOKEN') !== '';
const hasWebhookSecret = readEnv('WEBHOOK_SHARED_SECRET').length >= 16;

const SYNTHETIC_PORTAL_ID = '99000001';
const configuredPortalId = str('HUBSPOT_PORTAL_ID');
const portalId = sandboxMode ? SYNTHETIC_PORTAL_ID : configuredPortalId;
if (!sandboxMode) {
  const problems = [];
  if (!hasHubspotToken) problems.push('HUBSPOT_ACCESS_TOKEN is not set');
  if (!/^\d{1,12}$/.test(configuredPortalId)) problems.push('HUBSPOT_PORTAL_ID must be a numeric HubSpot portal ID');
  if (problems.length) throw new Error('Live mode (SANDBOX_MODE=false) refused: ' + problems.join('; ') + '. Fix the variables or keep SANDBOX_MODE=true.');
}

const now = (() => {
  const o = str('NOW_OVERRIDE');
  return o && !Number.isNaN(Date.parse(o)) ? new Date(o) : new Date();
})();

// ---- Trigger payload & webhook auth ----------------------------------------
function constantTimeEqual(a, b) {
  const x = String(a || '');
  const y = String(b || '');
  const len = Math.max(x.length, y.length);
  let diff = x.length ^ y.length;
  for (let i = 0; i < len; i++) diff |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  return diff === 0 && x.length > 0;
}
const SENSITIVE = new Set(['x-reconciliation-secret', 'authorization', 'cookie', 'proxy-authorization']);
const raw = $input.first().json || {};
const isWebhook = raw && typeof raw === 'object' && 'body' in raw && 'headers' in raw;
let requestedPeriod = '';
if (isWebhook) {
  const headers = Object.fromEntries(Object.entries(raw.headers || {}).map(([k, v]) => [String(k).toLowerCase(), v]));
  const query = raw.query && typeof raw.query === 'object' ? raw.query : {};
  const provided = headers['x-reconciliation-secret'] !== undefined ? headers['x-reconciliation-secret'] : query.reconciliation_secret;
  const valid = hasWebhookSecret && constantTimeEqual(provided, readEnv('WEBHOOK_SHARED_SECRET'));
  if (!sandboxMode && !valid) {
    throw new Error('Webhook rejected: WEBHOOK_SHARED_SECRET (16+ chars) must be set and sent as header x-reconciliation-secret (or ?reconciliation_secret=).');
  }
  const b = raw.body && typeof raw.body === 'object' ? raw.body : {};
  if (b.period !== undefined) requestedPeriod = String(b.period).trim();
}
const SAFE_TRIGGER = isWebhook ? { kind: 'webhook', headers: Object.keys(raw.headers || {}).filter((k) => !SENSITIVE.has(String(k).toLowerCase())) } : { kind: 'manual-or-schedule' };

// ---- Reconciliation period (YYYY-MM, UTC) ------------------------------------
const PERIOD_RE = /^(\d{4})-(0[1-9]|1[0-2])$/;
let period = requestedPeriod || str('RECONCILIATION_PERIOD');
let periodSource = requestedPeriod ? 'webhook' : period ? 'env' : 'default-previous-month';
if (!period) {
  const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
  period = `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}`;
}
const pm = period.match(PERIOD_RE);
if (!pm) throw new Error(`Invalid reconciliation period "${period}" (${periodSource}); expected YYYY-MM.`);
const periodStartMs = Date.UTC(Number(pm[1]), Number(pm[2]) - 1, 1);
const periodEndMs = Date.UTC(Number(pm[1]), Number(pm[2]), 1);
if (periodStartMs > now.getTime()) throw new Error(`Reconciliation period ${period} is in the future.`);
const periodOpen = periodEndMs > now.getTime();
if (periodOpen) warnings.push(`Period ${period} has not ended yet; churn recorded later this month will be missed by this run.`);

// ---- Clawback policy ----------------------------------------------------------
const windowDays = intIn('CLAWBACK_WINDOW_DAYS', 90, 1, 730);
const policy = str('CLAWBACK_POLICY', 'linear').toLowerCase();
if (!['linear', 'tiered', 'full'].includes(policy)) configErrors.push(`CLAWBACK_POLICY must be linear, tiered or full (got "${policy}")`);
const tiers = [];
for (const t of list('CLAWBACK_TIERS', '30:1,60:0.5,90:0.25')) {
  const m = t.match(/^(\d{1,4}):(\d+(?:\.\d+)?)$/);
  if (!m || Number(m[2]) > 1) { configErrors.push(`CLAWBACK_TIERS entry "${t}" must be <maxDays>:<rate 0..1>`); continue; }
  tiers.push({ maxDays: Number(m[1]), rate: m[2] });
}
tiers.sort((a, b) => a.maxDays - b.maxDays);
if (policy === 'tiered' && (!tiers.length || tiers[tiers.length - 1].maxDays > windowDays)) {
  configErrors.push('CLAWBACK_TIERS must be non-empty and no tier may exceed CLAWBACK_WINDOW_DAYS');
}

// ---- Currency & FX ------------------------------------------------------------
const payrollCurrency = str('PAYROLL_CURRENCY', 'USD').toUpperCase();
if (!/^[A-Z]{3}$/.test(payrollCurrency)) configErrors.push('PAYROLL_CURRENCY must be a 3-letter ISO code');
const fxRates = {};
for (const pair of list('FX_RATES')) {
  const m = pair.match(/^([A-Z]{3}):(\d+(?:\.\d{1,10})?)$/i);
  if (!m || Number(m[2]) <= 0) { configErrors.push(`FX_RATES entry "${pair}" must be CCY:rate (rate > 0, up to 10 decimals)`); continue; }
  fxRates[m[1].toUpperCase()] = m[2];
}
const fxAsOf = str('FX_RATES_AS_OF');
if (fxAsOf && !/^\d{4}-\d{2}-\d{2}$/.test(fxAsOf)) configErrors.push('FX_RATES_AS_OF must be YYYY-MM-DD');

// ---- Gates --------------------------------------------------------------------
const exportBlockers = [];
if (sandboxMode) exportBlockers.push('SANDBOX_MODE=true (synthetic fixture run)');
if (dryRun) exportBlockers.push('DRY_RUN=true');
if (!csvExportEnabled) exportBlockers.push('CSV_EXPORT_ENABLED is not true');
if (envBlocked) exportBlockers.push('n8n blocked $env access');
if (configErrors.length) exportBlockers.push(`${configErrors.length} configuration error(s)`);

const stampBlockers = [];
if (sandboxMode) stampBlockers.push('SANDBOX_MODE=true');
if (dryRun) stampBlockers.push('DRY_RUN=true');
if (!hubspotMutationsEnabled) stampBlockers.push('HUBSPOT_MUTATIONS_ENABLED is not true');
if (!csvExportEnabled) stampBlockers.push('Deals are only stamped after a successful CSV export (CSV_EXPORT_ENABLED is not true)');
if (envBlocked) stampBlockers.push('n8n blocked $env access');
if (configErrors.length) stampBlockers.push(`${configErrors.length} configuration error(s)`);

const props = {
  churnDate: prop('CHURN_DATE_PROPERTY', 'churn_date'),
  contractStart: prop('CONTRACT_START_PROPERTY', 'contract_start_date'),
  sdrOwner: prop('SDR_OWNER_PROPERTY', 'sdr_owner_id'),
  aeCommissionPaid: prop('AE_COMMISSION_PAID_PROPERTY', 'ae_commission_paid'),
  sdrCommissionPaid: prop('SDR_COMMISSION_PAID_PROPERTY', 'sdr_commission_paid'),
  exempt: prop('CLAWBACK_EXEMPT_PROPERTY', 'clawback_exempt'),
  stampStatus: prop('STAMP_STATUS_PROPERTY', 'clawback_status'),
  stampAe: prop('STAMP_AE_AMOUNT_PROPERTY', 'clawback_ae_amount'),
  stampSdr: prop('STAMP_SDR_AMOUNT_PROPERTY', 'clawback_sdr_amount'),
  stampReconciliationId: prop('STAMP_RECONCILIATION_ID_PROPERTY', 'clawback_reconciliation_id'),
  stampProcessedAt: prop('STAMP_PROCESSED_AT_PROPERTY', 'clawback_processed_at'),
};
const closedWonStage = prop('CLOSED_WON_STAGE', 'closedwon');
const closedLostStage = prop('CLOSED_LOST_STAGE', 'closedlost');
const dealProperties = [...new Set([
  'dealname', 'amount', 'deal_currency_code', 'closedate', 'dealstage', 'pipeline', 'hubspot_owner_id', 'hs_object_id',
  `hs_date_entered_${closedWonStage}`, `hs_date_entered_${closedLostStage}`, ...Object.values(props),
])];

const repPayrollRefs = {};
for (const pair of list('REP_PAYROLL_REF_MAP')) {
  const m = pair.match(/^(\d{1,20}):([A-Za-z0-9._-]{1,40})$/);
  if (m) repPayrollRefs[m[1]] = m[2];
  else warnings.push(`REP_PAYROLL_REF_MAP entry ignored (expected ownerId:REF): ${pair.slice(0, 40)}`);
}

const config = {
  runId: 'clb-' + now.toISOString().replace(/[-:.TZ]/g, '').slice(0, 14) + '-' + Math.random().toString(36).slice(2, 8),
  now: now.toISOString(),
  envBlocked,
  sandboxMode,
  dryRun,
  portalId,
  trigger: SAFE_TRIGGER,
  period: { id: period, source: periodSource, startMs: periodStartMs, endMs: periodEndMs, startIso: new Date(periodStartMs).toISOString(), endIso: new Date(periodEndMs).toISOString(), open: periodOpen },
  clawback: {
    windowDays,
    windowInclusive: safeOn('CLAWBACK_WINDOW_INCLUSIVE'),
    anchor: str('CLAWBACK_WINDOW_ANCHOR', 'contract_start').toLowerCase() === 'close_date' ? 'close_date' : 'contract_start',
    policy,
    tiers,
    retainCollectedCash: safeOff('CLAWBACK_RETAIN_COLLECTED_CASH'),
    minAmount: decIn('CLAWBACK_MIN_AMOUNT', '1.00'),
    detectClosedLostChurn: safeOn('DETECT_CLOSED_LOST_CHURN'),
  },
  commission: {
    source: str('COMMISSION_SOURCE', 'recorded_only').toLowerCase() === 'recorded_then_computed' ? 'recorded_then_computed' : 'recorded_only',
    aeRate: decIn('AE_COMMISSION_RATE', '0.10'),
    sdrRate: decIn('SDR_COMMISSION_RATE', '0.02'),
  },
  currency: {
    payroll: payrollCurrency,
    portalDefault: str('PORTAL_DEFAULT_CURRENCY', 'USD').toUpperCase(),
    fxRates,
    fxAsOf: fxAsOf || null,
  },
  guards: {
    maxTotal: decIn('MAX_TOTAL_CLAWBACK', '50000'),
    maxSingle: decIn('MAX_SINGLE_ADJUSTMENT', '15000'),
    blockOnPendingReview: safeOn('BLOCK_EXPORT_ON_PENDING_REVIEW'),
    requirePayrollRef: safeOff('REQUIRE_PAYROLL_REF'),
  },
  hubspot: {
    apiBase: str('HUBSPOT_API_BASE_URL', 'https://api.hubapi.com').replace(/\/+$/, ''),
    hasToken: hasHubspotToken,
    closedWonStage,
    closedLostStage,
    props,
    dealProperties,
    invoicesEnabled: safeOn('INVOICE_COLLECTION_ENABLED'),
    searchPageSize: intIn('HUBSPOT_SEARCH_PAGE_SIZE', 200, 10, 200),
    maxSearchPages: 50,
    mutationsEnabled: hubspotMutationsEnabled,
    stampAllowed: stampBlockers.length === 0,
    stampBlockers,
  },
  export: {
    enabled: csvExportEnabled,
    allowedByConfig: exportBlockers.length === 0,
    blockers: exportBlockers,
    dir: str('CSV_EXPORT_DIR', '/home/node/.n8n-files/clawback-exports').replace(/\/+$/, ''),
    includeDealName: safeOff('CSV_INCLUDE_DEAL_NAME'),
    utf8Bom: safeOff('CSV_UTF8_BOM'),
  },
  repPayrollRefs,
  configErrors,
  warnings,
};
if (/\.\.|[\0]/.test(config.export.dir)) configErrors.push('CSV_EXPORT_DIR must not contain ".." or NUL');

const safetyDecisions = [
  `Mode: ${sandboxMode ? 'SANDBOX (synthetic fixture, zero network calls)' : 'LIVE (read-only HubSpot search + batch reads)'}`,
  `Period: ${period} (${periodSource})${periodOpen ? ' [OPEN]' : ''}`,
  `Policy: ${policy}, window ${windowDays} days (${config.clawback.windowInclusive ? 'inclusive' : 'exclusive'}), anchor ${config.clawback.anchor}`,
  `CSV export: ${config.export.allowedByConfig ? 'ARMED (subject to guards)' : 'BLOCKED'}`,
  `HubSpot stamp: ${config.hubspot.stampAllowed ? 'ARMED (after export)' : 'BLOCKED'}`,
  `Commission source: ${config.commission.source}`,
];
return [{ json: { config, safetyDecisions } }];

// ============================================================================
// Build Churned-Deal Search  (LIVE path)
// One read-only CRM search (POST /crm/v3/objects/deals/search) with up to two
// OR'ed filter groups:
//   A. churn_date within the reconciliation period
//   B. (optional) deals now in the closed-lost stage that entered it during the
//      period AND have a recorded closed-won entry date ("closed-lost churn")
// Sorted by hs_object_id for stable pagination; the HTTP node pages with `after`.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const h = config.hubspot;
const startMs = String(config.period.startMs);
const endMs = String(config.period.endMs);
const filterGroups = [
  { filters: [
    { propertyName: h.props.churnDate, operator: 'GTE', value: startMs },
    { propertyName: h.props.churnDate, operator: 'LT', value: endMs },
  ] },
];
if (config.clawback.detectClosedLostChurn) {
  filterGroups.push({ filters: [
    { propertyName: 'dealstage', operator: 'EQ', value: h.closedLostStage },
    { propertyName: `hs_date_entered_${h.closedLostStage}`, operator: 'GTE', value: startMs },
    { propertyName: `hs_date_entered_${h.closedLostStage}`, operator: 'LT', value: endMs },
    { propertyName: `hs_date_entered_${h.closedWonStage}`, operator: 'HAS_PROPERTY' },
  ] },
  );
}
const body = {
  filterGroups,
  properties: h.dealProperties,
  sorts: [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }],
  limit: h.searchPageSize,
};
if (JSON.stringify(body).length > 3000) throw new Error('Search request exceeds HubSpot\'s 3,000-character limit; shorten the configured property names.');
return [{ json: { url: `${h.apiBase}/crm/v3/objects/deals/search`, body } }];

// ============================================================================
// Collect Search Pages  (LIVE path) - FAIL CLOSED
// Any failed page, a result set above HubSpot's 10,000-result search cap, or
// pagination stopped by the page limit aborts the run: a payroll file built
// from partial data would be silently wrong.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const pages = $input.all().map((i) => i.json);
const failed = pages.find((p) => p && p.error);
if (failed) throw new Error('HubSpot deal search failed; aborting (no partial reconciliation): ' + String(failed.error.message || failed.error).slice(0, 300));
const total = pages.length && typeof pages[0].total === 'number' ? pages[0].total : null;
if (total !== null && total >= 10000) {
  throw new Error(`HubSpot search matched ${total} deals; the search API cannot page past 10,000. Narrow the period or filters.`);
}
const last = pages[pages.length - 1] || {};
if (pages.length >= config.hubspot.maxSearchPages && last.paging && last.paging.next) {
  throw new Error(`Search pagination stopped at ${pages.length} pages with more results pending; aborting to avoid an incomplete reconciliation.`);
}
const seen = new Map();
for (const p of pages) for (const r of p.results || []) if (r && r.id && !seen.has(String(r.id))) seen.set(String(r.id), r);
const deals = [...seen.values()];
const warnings = [];
if (total !== null && total !== deals.length) warnings.push(`Search reported total=${total} but ${deals.length} unique deals were collected (records may have changed during paging).`);
return [{ json: { source: 'hubspot-api', complete: true, deals, dealCount: deals.length, pages: pages.length, collectionWarnings: warnings } }];

// ============================================================================
// Build Invoice Association Requests  (LIVE path)
// v4 batch association read (read-only POST), 100 deal IDs per request.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const { deals } = $input.first().json;
const ids = deals.map((d) => String(d.id));
const out = [];
for (let i = 0; i < ids.length; i += 100) {
  out.push({ json: { url: `${config.hubspot.apiBase}/crm/v4/associations/deals/invoices/batch/read`, body: { inputs: ids.slice(i, i + 100).map((id) => ({ id })) } } });
}
return out;

// ============================================================================
// Build Invoice Read Requests  (LIVE path)
// Turns association responses into a deal->invoice map and batch-read
// requests (100 invoices each). Emits {skip:true} when there is nothing to read.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const responses = $input.all().map((i) => i.json);
const assocMap = {};
let assocFailed = null;
for (const r of responses) {
  if (r.error) { assocFailed = String(r.error.message || r.error).slice(0, 300); continue; }
  for (const row of r.results || []) {
    const from = String(row.from && row.from.id);
    assocMap[from] = (row.to || []).map((t) => String(t.toObjectId));
  }
}
const invoiceIds = [...new Set(Object.values(assocMap).flat())];
if (assocFailed || !invoiceIds.length) return [{ json: { skip: true, assocMap, assocFailed } }];
const out = [];
for (let i = 0; i < invoiceIds.length; i += 100) {
  out.push({ json: {
    skip: false, assocMap, assocFailed: null,
    url: `${config.hubspot.apiBase}/crm/v3/objects/invoices/batch/read`,
    body: { inputs: invoiceIds.slice(i, i + 100).map((id) => ({ id })), properties: ['hs_invoice_status', 'hs_amount_billed', 'hs_balance_due', 'hs_currency'] },
  } });
}
return out;

// ============================================================================
// Normalize Deal Records
// Unifies the sandbox fixture and the live search (+ optional invoices) into
// one shape: { records: [{ deal, invoices, invoiceLookup }], fx, repPayrollRefs }.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const first = $input.first().json || {};
const warnings = [];
let deals;
let invoicesByDeal = {};
let invoiceLookup = 'disabled';
let source;

if (first.source === 'synthetic-fixture') {
  source = first.source;
  deals = first.deals;
  invoicesByDeal = first.invoicesByDeal || {};
  invoiceLookup = 'ok';
} else {
  const search = $('Collect Search Pages').first().json;
  source = search.source;
  deals = search.deals;
  warnings.push(...search.collectionWarnings);
  if (config.hubspot.invoicesEnabled && deals.length) {
    let plan = null;
    try { plan = $('Build Invoice Read Requests').first().json; } catch (e) { plan = null; }
    if (!plan) invoiceLookup = 'failed';
    else if (plan.assocFailed) { invoiceLookup = 'failed'; warnings.push('Invoice associations could not be read: ' + plan.assocFailed); }
    else {
      invoiceLookup = 'ok';
      const byId = {};
      if (!plan.skip) {
        for (const r of $input.all().map((i) => i.json)) {
          if (r.error) { invoiceLookup = 'failed'; warnings.push('Invoice batch read failed: ' + String(r.error.message || r.error).slice(0, 200)); continue; }
          for (const inv of r.results || []) byId[String(inv.id)] = inv;
        }
      }
      for (const [dealId, ids] of Object.entries(plan.assocMap || {})) invoicesByDeal[dealId] = ids.map((id) => byId[id]).filter(Boolean);
    }
  }
}

// FX + payroll refs: env first; sandbox falls back to the fixture's synthetic values.
let fx = { rates: config.currency.fxRates, asOf: config.currency.fxAsOf, source: 'env' };
let repPayrollRefs = config.repPayrollRefs;
if (config.sandboxMode) {
  if (!Object.keys(fx.rates).length && first.sandboxFx) fx = { rates: first.sandboxFx.rates, asOf: first.sandboxFx.asOf, source: 'fixture' };
  if (!Object.keys(repPayrollRefs).length && first.sandboxRepPayrollRefs) repPayrollRefs = first.sandboxRepPayrollRefs;
}

const records = deals.map((d) => ({ deal: { id: String(d.id), properties: d.properties || {} }, invoices: invoicesByDeal[String(d.id)] || [], invoiceLookup }));
return [{ json: { source, complete: true, records, fx, repPayrollRefs, invoiceLookup, collectionWarnings: warnings } }];

// ============================================================================
// Clawback Calculator  (pure computation, no network)
// For every churned deal:
//   1. Idempotency / exemption / data-quality checks (each with a reason code)
//   2. Churn date (churn_date property, or closed-lost stage entry) and window
//      anchor (contract start -> closed-won entry -> close date), UTC days
//   3. Clawback rate from the policy (linear | tiered | full) as an exact fraction
//   4. Per role (AE, SDR): recorded (or computed) commission, FX to the payroll
//      currency, optional collected-cash retention, de-minimis threshold
//   5. Totals, deterministic adjustment / reconciliation IDs, export guards
// Money is handled as BigInt minor units with a single half-up rounding per
// step; no floating-point amounts are ever summed.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const input = $input.first().json;
const C = config.clawback;
const P = config.hubspot.props;
const DAY = 86400000;

// ---- Pure-JS SHA-256 (no require; identical to node:crypto output)
function utf8Bytes(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      const d = str.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00); i++; }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

function sha256(str) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const bytes = utf8Bytes(str);
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255);
  bytes.push((lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const W = new Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + t * 4;
      W[t] = ((bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + W[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map((x) => x.toString(16).padStart(8, '0')).join('');
}

// ---------------------------------------------------------------- money
const ZERO_DP = new Set(['JPY', 'KRW', 'CLP', 'VND', 'ISK', 'UGX', 'XAF', 'XOF', 'PYG', 'RWF']);
const THREE_DP = new Set(['KWD', 'BHD', 'OMR', 'JOD', 'TND', 'LYD', 'IQD']);
const dpOf = (ccy) => (ZERO_DP.has(ccy) ? 0 : THREE_DP.has(ccy) ? 3 : 2);
const pow10 = (n) => 10n ** BigInt(n);
const roundDiv = (num, den) => (num * 2n + den) / (den * 2n); // half-up, num >= 0, den > 0
/** Strict decimal parser -> { ok, minor (BigInt) } ; accepts 1234.56 or 1,234.56 */
function parseMoney(raw, dp) {
  if (raw === null || raw === undefined) return { ok: false, empty: true };
  const s = String(raw).trim();
  if (s === '') return { ok: false, empty: true };
  if (!/^(\d+|\d{1,3}(,\d{3})+)(\.\d+)?$/.test(s)) return { ok: false, empty: false };
  const [intPart, frac = ''] = s.replace(/,/g, '').split('.');
  const scale = frac.length;
  const asInt = BigInt(intPart + frac);
  const minor = scale <= dp ? asInt * pow10(dp - scale) : roundDiv(asInt, pow10(scale - dp));
  return { ok: true, minor };
}
/** Decimal string -> exact fraction {num, den} */
function frac(dec) {
  const [i, f = ''] = String(dec).split('.');
  return { num: BigInt(i + f), den: pow10(f.length) };
}
function fmt(minor, dp, negative = false) {
  const m = minor < 0n ? -minor : minor;
  const s = m.toString().padStart(dp + 1, '0');
  const body = dp ? `${s.slice(0, -dp)}.${s.slice(-dp)}` : s;
  return (negative || minor < 0n) && m !== 0n ? `-${body}` : body;
}
// Display-only ratio, rounded half-up (money math never uses this value).
const ratio = (num, den, places = 6) => (den === 0n ? '0' : (Number(roundDiv(num * pow10(places), den)) / 10 ** places).toFixed(places));

// ---------------------------------------------------------------- dates
function parseDay(raw) {
  if (raw === null || raw === undefined) return { ok: false, empty: true };
  const s = String(raw).trim();
  if (s === '') return { ok: false, empty: true };
  let ms = NaN;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    const [y, m, d] = s.split('-').map(Number);
    ms = Date.UTC(y, m - 1, d);
    if (new Date(ms).getUTCDate() !== d) ms = NaN; // rejects 2026-02-30
  } else if (/^\d{12,14}$/.test(s)) ms = Number(s);
  else if (/^\d{4}-\d{2}-\d{2}T/.test(s)) ms = Date.parse(s);
  if (!Number.isFinite(ms) || ms < Date.UTC(1990, 0, 1) || ms > Date.UTC(2100, 0, 1)) return { ok: false, empty: false };
  const day = Math.floor(ms / DAY);
  return { ok: true, day, iso: new Date(day * DAY).toISOString().slice(0, 10) };
}
const truthy = (v) => ['true', '1', 'yes'].includes(String(v ?? '').trim().toLowerCase());

// ---------------------------------------------------------------- policy
function clawbackRate(days) {
  const inWindow = C.windowInclusive ? days <= C.windowDays : days < C.windowDays;
  if (!inWindow) return null;
  if (C.policy === 'full') return { num: 1n, den: 1n };
  if (C.policy === 'tiered') {
    const tier = C.tiers.find((t) => days <= t.maxDays);
    return tier ? frac(tier.rate) : { num: 0n, den: 1n };
  }
  return { num: BigInt(Math.max(0, C.windowDays - days)), den: BigInt(C.windowDays) };
}

// ---------------------------------------------------------------- setup
const payCcy = config.currency.payroll;
const payDp = dpOf(payCcy);
const minClaw = parseMoney(C.minAmount, payDp).minor;
const maxSingle = parseMoney(config.guards.maxSingle, payDp).minor;
const maxTotal = parseMoney(config.guards.maxTotal, payDp).minor;
const fxRates = (input.fx && input.fx.rates) || {};
const refs = input.repPayrollRefs || {};
const periodStartDay = Math.floor(config.period.startMs / DAY);
const periodEndDay = Math.floor(config.period.endMs / DAY);
const todayDay = Math.floor(Date.parse(config.now) / DAY);
const wonKey = `hs_date_entered_${config.hubspot.closedWonStage}`;
const lostKey = `hs_date_entered_${config.hubspot.closedLostStage}`;

const rows = [];
const deals = [];
const fxUsed = new Set();
const pendingIssues = [];

for (const rec of input.records) {
  const p = rec.deal.properties || {};
  const dealId = rec.deal.id;
  const dealName = String(p.dealname || '');
  const dealOut = { dealId, dealName, status: null, reasonCode: null, notes: [] };
  const finish = (status, reasonCode, note) => { dealOut.status = status; dealOut.reasonCode = reasonCode; if (note) dealOut.notes.push(note); deals.push(dealOut); };

  if (String(p[P.stampReconciliationId] || '').trim()) { finish('SKIP_ALREADY_RECONCILED', 'RECONCILIATION_ID_PRESENT', `Already in ${String(p[P.stampReconciliationId]).slice(0, 40)}`); continue; }
  if (truthy(p[P.exempt])) { finish('EXEMPT', 'CLAWBACK_EXEMPT_FLAG'); continue; }

  // Churn date & source
  let churn = parseDay(p[P.churnDate]);
  let churnSource = 'churn_date_property';
  if (!churn.ok && !churn.empty) { finish('PENDING_REVIEW', 'INVALID_CHURN_DATE', `${P.churnDate}="${String(p[P.churnDate]).slice(0, 30)}"`); continue; }
  if (churn.empty) {
    const lost = parseDay(p[lostKey]);
    const won = parseDay(p[wonKey]);
    if (C.detectClosedLostChurn && String(p.dealstage) === config.hubspot.closedLostStage && lost.ok && won.ok) { churn = lost; churnSource = 'closed_lost_stage'; }
    else { finish('NOT_CHURNED', 'NO_CHURN_SIGNAL'); continue; }
  }
  if (churn.day < periodStartDay || churn.day >= periodEndDay) { finish('OUT_OF_PERIOD', 'CHURN_OUTSIDE_PERIOD', `churn ${churn.iso}`); continue; }
  if (churn.day > todayDay) { finish('NOT_YET_EFFECTIVE', 'CHURN_IN_FUTURE', `churn ${churn.iso}`); continue; }

  // Window anchor
  let anchor = null;
  let anchorSource = null;
  const candidates = C.anchor === 'contract_start' ? [[P.contractStart, 'contract_start'], [wonKey, 'closed_won_entered'], ['closedate', 'close_date']] : [[wonKey, 'closed_won_entered'], ['closedate', 'close_date']];
  let anchorError = null;
  for (const [key, label] of candidates) {
    const d = parseDay(p[key]);
    if (d.ok) { anchor = d; anchorSource = label; break; }
    if (!d.empty && !anchorError) anchorError = `${key}="${String(p[key]).slice(0, 30)}"`;
  }
  if (!anchor) { finish('PENDING_REVIEW', anchorError ? 'INVALID_ANCHOR_DATE' : 'MISSING_ANCHOR_DATE', anchorError); continue; }
  if (anchorError && anchorSource !== 'contract_start' && C.anchor === 'contract_start' && String(p[P.contractStart] || '').trim()) {
    finish('PENDING_REVIEW', 'INVALID_CONTRACT_START', anchorError); continue;
  }
  const daysActive = churn.day - anchor.day;
  if (daysActive < 0) { finish('PENDING_REVIEW', 'CHURN_BEFORE_ANCHOR', `churn ${churn.iso} < ${anchorSource} ${anchor.iso}`); continue; }
  const rate = clawbackRate(daysActive);
  if (!rate) { finish('OUTSIDE_WINDOW', 'BEYOND_CLAWBACK_WINDOW', `day ${daysActive} > ${C.windowDays}`); continue; }

  // Currency, amount, collected cash
  const ccyRaw = String(p.deal_currency_code || '').trim().toUpperCase();
  const dealCcy = ccyRaw || config.currency.portalDefault;
  if (!ccyRaw) dealOut.notes.push(`deal_currency_code empty; assumed ${dealCcy}`);
  const dealDp = dpOf(dealCcy);
  const amount = parseMoney(p.amount, dealDp);
  let fx = null;
  if (dealCcy === payCcy) fx = { rate: '1', num: 1n, den: 1n };
  else if (fxRates[dealCcy]) { fx = { rate: fxRates[dealCcy], ...frac(fxRates[dealCcy]) }; fxUsed.add(dealCcy); }

  let collected = { num: 1n, den: 1n, display: '' };
  let collectedIssue = null;
  if (C.retainCollectedCash) {
    if (rec.invoiceLookup !== 'ok') collectedIssue = 'INVOICE_DATA_UNAVAILABLE';
    else if (!amount.ok || amount.minor === 0n) collectedIssue = 'INVALID_DEAL_AMOUNT';
    else {
      let paid = 0n;
      for (const inv of rec.invoices || []) {
        const ip = inv.properties || {};
        const st = String(ip.hs_invoice_status || '').toLowerCase();
        if (st === 'voided' || st === 'draft') continue;
        const invCcy = String(ip.hs_currency || dealCcy).toUpperCase();
        if (invCcy !== dealCcy) { collectedIssue = 'INVOICE_CURRENCY_MISMATCH'; break; }
        const billed = parseMoney(ip.hs_amount_billed, dealDp);
        const due = parseMoney(ip.hs_balance_due || '0', dealDp);
        if (!billed.ok || !due.ok) { collectedIssue = 'INVALID_INVOICE_AMOUNT'; break; }
        if (billed.minor > due.minor) paid += billed.minor - due.minor;
      }
      if (paid > amount.minor) paid = amount.minor;
      collected = { num: amount.minor - paid, den: amount.minor, display: ratio(paid, amount.minor, 4) };
    }
  }

  // Roles
  const roles = [];
  const aeId = String(p.hubspot_owner_id || '').trim();
  roles.push({ role: 'AE', ownerId: aeId, paidKey: P.aeCommissionPaid, rateDec: config.commission.aeRate });
  const sdrId = String(p[P.sdrOwner] || '').trim();
  if (sdrId) roles.push({ role: 'SDR', ownerId: sdrId, paidKey: P.sdrCommissionPaid, rateDec: config.commission.sdrRate });

  for (const r of roles) {
    const row = {
      adjustmentId: 'ADJ-' + sha256(`${config.period.id}|${dealId}|${r.role}|${r.ownerId}`).slice(0, 16).toUpperCase(),
      dealId, dealName, role: r.role, repOwnerId: r.ownerId, repPayrollRef: refs[r.ownerId] || '',
      anchorDate: anchor.iso, anchorSource, churnDate: churn.iso, churnSource, daysActive, windowDays: C.windowDays,
      policy: C.policy, clawbackRate: ratio(rate.num, rate.den), collectedRatio: collected.display,
      commissionSource: '', originalCommission: '', originalCurrency: dealCcy, fxRate: fx ? fx.rate : '',
      commissionPayroll: '', clawbackAmount: '', clawbackMinor: 0, payrollCurrency: payCcy,
      status: 'CLAWBACK', reasonCode: '', notes: [...dealOut.notes],
    };
    const pend = (code, note) => { row.status = 'PENDING_REVIEW'; row.reasonCode = code; if (note) row.notes.push(note); };
    rows.push(row);
    if (!/^\d{1,20}$/.test(r.ownerId)) { pend(r.role === 'AE' ? 'MISSING_AE_OWNER' : 'INVALID_SDR_OWNER'); continue; }
    if (collectedIssue) { pend(collectedIssue); continue; }
    if (!fx) { pend('FX_RATE_MISSING', `No FX_RATES entry for ${dealCcy}->${payCcy}`); continue; }

    let basis = parseMoney(p[r.paidKey], dealDp);
    if (basis.ok) row.commissionSource = 'recorded';
    else if (!basis.empty) { pend('INVALID_COMMISSION_AMOUNT', `${r.paidKey}="${String(p[r.paidKey]).slice(0, 30)}"`); continue; }
    else if (config.commission.source === 'recorded_then_computed') {
      if (!amount.ok) { pend('INVALID_DEAL_AMOUNT', `amount="${String(p.amount ?? '').slice(0, 30)}"`); continue; }
      const rf = frac(r.rateDec);
      basis = { ok: true, minor: roundDiv(amount.minor * rf.num, rf.den) };
      row.commissionSource = `computed@${r.rateDec}`;
      row.notes.push('Commission computed from rate; verify against the commission ledger');
    } else { pend('MISSING_RECORDED_COMMISSION', `${r.paidKey} is empty`); continue; }
    if (amount.ok && basis.minor > amount.minor) { pend('COMMISSION_EXCEEDS_DEAL_AMOUNT'); continue; }

    row.originalCommission = fmt(basis.minor, dealDp);
    const payMinor = roundDiv(basis.minor * fx.num * pow10(payDp), fx.den * pow10(dealDp));
    row.commissionPayroll = fmt(payMinor, payDp);
    if (payMinor === 0n) { row.status = 'NO_COMMISSION_PAID'; row.reasonCode = 'ZERO_COMMISSION'; row.clawbackAmount = fmt(0n, payDp); continue; }
    const claw = roundDiv(payMinor * rate.num * collected.num, rate.den * collected.den);
    row.clawbackMinor = Number(claw);
    row.clawbackAmount = fmt(claw, payDp, true);
    if (claw < minClaw) { row.status = 'BELOW_DE_MINIMIS'; row.reasonCode = 'BELOW_CLAWBACK_MIN_AMOUNT'; continue; }
    if (!row.repPayrollRef) {
      if (config.guards.requirePayrollRef) { pend('MISSING_PAYROLL_REF'); continue; }
      row.notes.push('No payroll reference mapped for this rep');
    }
    if (claw > maxSingle) row.notes.push('EXCEEDS_MAX_SINGLE_ADJUSTMENT');
  }

  const own = rows.filter((x) => x.dealId === dealId);
  if (own.some((x) => x.status === 'PENDING_REVIEW')) {
    // Hold the whole deal: a valid AE row must not reach payroll while its SDR
    // row (or vice versa) is unresolved, or a re-run could pay it twice.
    for (const x of own) if (x.status === 'CLAWBACK') { x.status = 'HELD_DEAL_PENDING_REVIEW'; x.notes.push('Held until the deal\'s other row is resolved'); }
    finish('PENDING_REVIEW', own.find((x) => x.status === 'PENDING_REVIEW').reasonCode);
  }
  else if (own.some((x) => x.status === 'CLAWBACK')) finish('CLAWBACK', 'WITHIN_CLAWBACK_WINDOW', `day ${daysActive}/${C.windowDays}`);
  else finish('NO_CLAWBACK_DUE', own.map((x) => x.reasonCode).join('+'), `day ${daysActive}/${C.windowDays}`);
}

// ---------------------------------------------------------------- totals
const claws = rows.filter((r) => r.status === 'CLAWBACK');
const sumMinor = claws.reduce((s, r) => s + BigInt(r.clawbackMinor), 0n);
const byRep = {};
for (const r of claws) {
  const k = `${r.role}:${r.repOwnerId}`;
  byRep[k] = byRep[k] || { role: r.role, repOwnerId: r.repOwnerId, repPayrollRef: r.repPayrollRef, adjustments: 0, minor: 0n };
  byRep[k].adjustments++;
  byRep[k].minor += BigInt(r.clawbackMinor);
}
const repTotals = Object.values(byRep)
  .sort((a, b) => (a.role === b.role ? a.repOwnerId.localeCompare(b.repOwnerId) : a.role.localeCompare(b.role)))
  .map((t) => ({ role: t.role, repOwnerId: t.repOwnerId, repPayrollRef: t.repPayrollRef, adjustments: t.adjustments, total: fmt(t.minor, payDp, true) }));
const statusCounts = {};
for (const d of deals) statusCounts[d.status] = (statusCounts[d.status] || 0) + 1;
const rowStatusCounts = {};
for (const r of rows) rowStatusCounts[r.status] = (rowStatusCounts[r.status] || 0) + 1;

const fingerprint = [...claws.map((r) => `${r.adjustmentId}:${r.clawbackMinor}`), ...deals.map((d) => `${d.dealId}:${d.status}`)].sort().join('|');
const reconciliationId = `REC-${config.period.id}-${sha256(fingerprint).slice(0, 10).toUpperCase()}`;

// ---------------------------------------------------------------- guards
const guardFailures = [];
if (sumMinor > maxTotal) guardFailures.push(`Total clawback ${fmt(sumMinor, payDp)} ${payCcy} exceeds MAX_TOTAL_CLAWBACK ${config.guards.maxTotal}`);
const big = claws.filter((r) => BigInt(r.clawbackMinor) > maxSingle);
if (big.length) guardFailures.push(`${big.length} adjustment(s) exceed MAX_SINGLE_ADJUSTMENT ${config.guards.maxSingle}: ${big.map((r) => r.adjustmentId).join(', ')}`);
const pendingDeals = deals.filter((d) => d.status === 'PENDING_REVIEW');
if (pendingDeals.length && config.guards.blockOnPendingReview) guardFailures.push(`${pendingDeals.length} deal(s) need review (BLOCK_EXPORT_ON_PENDING_REVIEW=true)`);
if (fxUsed.size && !input.fx.asOf) guardFailures.push(`FX conversion used (${[...fxUsed].join(', ')}) but FX_RATES_AS_OF is not set`);
if (!input.complete) guardFailures.push('Data collection was incomplete');
if (config.configErrors.length) guardFailures.push(...config.configErrors.map((e) => `Config: ${e}`));

return [{
  json: {
    reconciliationId,
    period: config.period.id,
    payrollCurrency: payCcy,
    policy: { policy: C.policy, windowDays: C.windowDays, inclusive: C.windowInclusive, anchor: C.anchor, tiers: C.tiers, retainCollectedCash: C.retainCollectedCash, minAmount: C.minAmount, commissionSource: config.commission.source },
    fx: { ...input.fx, used: [...fxUsed] },
    source: input.source,
    invoiceLookup: input.invoiceLookup,
    rows,
    deals,
    totals: { adjustments: claws.length, total: fmt(sumMinor, payDp, true), totalMinor: Number(sumMinor), byRep: repTotals },
    statusCounts,
    rowStatusCounts,
    guards: { passed: guardFailures.length === 0, failures: guardFailures },
    collectionWarnings: input.collectionWarnings || [],
  },
}];

// ============================================================================
// CSV Builder & Integrity
// Produces three files, each with a SHA-256 checksum:
//   1. payroll CSV  - CLAWBACK adjustments only (negative amounts), import-ready
//   2. audit CSV    - every evaluated deal / role with status and reason code
//   3. manifest JSON - totals, per-rep totals, guards, checksums, policy snapshot
// RFC 4180 quoting, CRLF line endings, and a formula-injection guard: any text
// cell starting with = + - @ TAB or CR gets a leading apostrophe. Plain numbers
// such as -1234.56 are left untouched.
// Files are named DRAFT-... whenever export is not allowed.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const r = $input.first().json;

// ---- Pure-JS SHA-256 (no require; identical to node:crypto output)
function utf8Bytes(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      const d = str.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00); i++; }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

function sha256(str) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const bytes = utf8Bytes(str);
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255);
  bytes.push((lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const W = new Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + t * 4;
      W[t] = ((bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + W[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map((x) => x.toString(16).padStart(8, '0')).join('');
}

const NUMERIC = /^-?\d+(\.\d+)?$/;
function cell(v) {
  let s = v === null || v === undefined ? '' : Array.isArray(v) ? v.join('; ') : String(v);
  s = s.replace(/\r\n|\r|\n/g, ' ');
  if (!NUMERIC.test(s) && /^[=+\-@\t]/.test(s)) s = "'" + s;
  return /[",]/.test(s) || /^\s|\s$/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}
const toCsv = (header, records) => (config.export.utf8Bom ? '﻿' : '') + [header, ...records].map((row) => row.map(cell).join(',')).join('\r\n') + '\r\n';

const includeName = config.export.includeDealName;
const payrollHeader = ['reconciliation_id', 'adjustment_id', 'period', 'rep_role', 'rep_hubspot_owner_id', 'rep_payroll_ref', 'deal_id', ...(includeName ? ['deal_name'] : []),
  'anchor_date', 'anchor_source', 'churn_date', 'churn_source', 'days_active', 'window_days', 'clawback_policy', 'clawback_rate', 'collected_ratio',
  'commission_source', 'original_commission', 'original_currency', 'fx_rate', 'commission_in_payroll_currency', 'clawback_amount', 'payroll_currency', 'notes'];
const payrollRows = r.rows.filter((x) => x.status === 'CLAWBACK').map((x) => [
  r.reconciliationId, x.adjustmentId, r.period, x.role, x.repOwnerId, x.repPayrollRef, x.dealId, ...(includeName ? [x.dealName] : []),
  x.anchorDate, x.anchorSource, x.churnDate, x.churnSource, x.daysActive, x.windowDays, x.policy, x.clawbackRate, x.collectedRatio,
  x.commissionSource, x.originalCommission, x.originalCurrency, x.fxRate, x.commissionPayroll, x.clawbackAmount, x.payrollCurrency, x.notes,
]);

const auditHeader = ['reconciliation_id', 'period', 'deal_id', ...(includeName ? ['deal_name'] : []), 'deal_status', 'deal_reason_code', 'adjustment_id', 'rep_role', 'rep_hubspot_owner_id',
  'row_status', 'row_reason_code', 'anchor_date', 'churn_date', 'churn_source', 'days_active', 'clawback_rate', 'original_commission', 'original_currency', 'fx_rate', 'clawback_amount', 'payroll_currency', 'notes'];
const auditRows = [];
for (const d of r.deals) {
  const own = r.rows.filter((x) => x.dealId === d.dealId);
  if (!own.length) {
    auditRows.push([r.reconciliationId, r.period, d.dealId, ...(includeName ? [d.dealName] : []), d.status, d.reasonCode, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', d.notes]);
    continue;
  }
  for (const x of own) {
    auditRows.push([r.reconciliationId, r.period, d.dealId, ...(includeName ? [d.dealName] : []), d.status, d.reasonCode, x.adjustmentId, x.role, x.repOwnerId,
      x.status, x.reasonCode, x.anchorDate, x.churnDate, x.churnSource, x.daysActive, x.clawbackRate, x.originalCommission, x.originalCurrency, x.fxRate,
      x.status === 'CLAWBACK' ? x.clawbackAmount : '', x.payrollCurrency, x.notes]);
  }
}

const payrollCsv = toCsv(payrollHeader, payrollRows);
const auditCsv = toCsv(auditHeader, auditRows);
const exportBlockers = [...config.export.blockers, ...r.guards.failures];
const exportAllowed = exportBlockers.length === 0;
const prefix = exportAllowed ? '' : 'DRAFT-';
const base = `clawback-${r.period}-${r.reconciliationId}`;
const files = [
  { kind: 'payroll', fileName: `${prefix}${base}-payroll.csv`, mimeType: 'text/csv', content: payrollCsv, rows: payrollRows.length },
  { kind: 'audit', fileName: `${prefix}${base}-audit.csv`, mimeType: 'text/csv', content: auditCsv, rows: auditRows.length },
];
for (const f of files) {
  f.sha256 = sha256(f.content);
  f.bytes = utf8Bytes(f.content).length;
}
const manifest = {
  schemaVersion: '1.0.0',
  generator: 'n8n-hubspot-commission-clawback-churn-reconciliation-calculator',
  reconciliationId: r.reconciliationId,
  period: r.period,
  generatedAt: config.now,
  runId: config.runId,
  source: r.source,
  portalId: config.portalId,
  exportAllowed,
  exportBlockers,
  payrollCurrency: r.payrollCurrency,
  policy: r.policy,
  fx: r.fx,
  totals: r.totals,
  dealStatusCounts: r.statusCounts,
  rowStatusCounts: r.rowStatusCounts,
  files: files.map((f) => ({ kind: f.kind, fileName: f.fileName, rows: f.rows, bytes: f.bytes, sha256: f.sha256 })),
  collectionWarnings: r.collectionWarnings,
};
const manifestContent = JSON.stringify(manifest, null, 2) + '\n';
files.push({ kind: 'manifest', fileName: `${prefix}${base}-manifest.json`, mimeType: 'application/json', content: manifestContent, rows: null, sha256: sha256(manifestContent), bytes: utf8Bytes(manifestContent).length });

return files.map((f) => ({
  json: {
    kind: f.kind,
    fileName: f.fileName,
    path: `${config.export.dir}/${f.fileName}`,
    rows: f.rows,
    bytes: f.bytes,
    sha256: f.sha256,
    exportAllowed,
    exportBlockers,
    reconciliationId: r.reconciliationId,
    content: f.content,
  },
  binary: {
    data: { data: Buffer.from(f.content, 'utf8').toString('base64'), mimeType: f.mimeType, fileName: f.fileName, fileExtension: f.kind === 'manifest' ? 'json' : 'csv' },
  },
}));

// ============================================================================
// Dry-Run Preview  (export blocked)
// Summarises the DRAFT files (downloadable from this execution's binary data)
// and every reason the export and the HubSpot stamp were blocked.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const files = $input.all().map((i) => i.json);
const calc = $('Clawback Calculator').first().json;
return [{
  json: {
    mode: 'dry-run',
    reconciliationId: calc.reconciliationId,
    exportBlockedBy: files[0] ? files[0].exportBlockers : [],
    stampBlockedBy: config.hubspot.stampBlockers,
    draftFiles: files.map((f) => ({ kind: f.kind, fileName: f.fileName, rows: f.rows, bytes: f.bytes, sha256: f.sha256 })),
    wouldWriteTo: config.export.dir,
    payrollPreview: (files.find((f) => f.kind === 'payroll') || {}).content || '',
  },
}];

// ============================================================================
// Export Result
// Confirms all three files were written (one item per file from the write
// node). Anything less stops the run before any HubSpot stamp.
// ============================================================================
const written = $input.all().map((i) => i.json);
const planned = $('CSV Builder & Integrity').all().map((i) => i.json);
if (written.length !== planned.length) {
  throw new Error(`Export incomplete: ${written.length}/${planned.length} files written. Deals were NOT stamped; fix the export target and re-run.`);
}
return [{
  json: {
    mode: 'exported',
    reconciliationId: planned[0].reconciliationId,
    files: planned.map((f) => ({ kind: f.kind, path: f.path, rows: f.rows, bytes: f.bytes, sha256: f.sha256 })),
  },
}];

// ============================================================================
// Build Deal Stamp Batches  (after a successful export, stamping armed)
// Stamps only conclusively evaluated deals; PENDING_REVIEW deals stay
// unstamped so the next run re-evaluates them. 100 deals per batch update.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const calc = $('Clawback Calculator').first().json;
const P = config.hubspot.props;
const STAMPABLE = new Set(['CLAWBACK', 'NO_CLAWBACK_DUE', 'OUTSIDE_WINDOW', 'EXEMPT']);
const toAbs = (s) => String(s || '').replace(/^-/, '');
const inputs = [];
for (const d of calc.deals.filter((x) => STAMPABLE.has(x.status))) {
  const rows = calc.rows.filter((r) => r.dealId === d.dealId && r.status === 'CLAWBACK');
  const sum = (role) => rows.filter((r) => r.role === role).reduce((s, r) => s + r.clawbackMinor, 0);
  const dp = (calc.totals.total.split('.')[1] || '').length;
  const asDec = (minor) => (dp ? (minor / 10 ** dp).toFixed(dp) : String(minor));
  const properties = { [P.stampStatus]: d.status, [P.stampReconciliationId]: calc.reconciliationId, [P.stampProcessedAt]: config.now };
  if (P.stampAe) properties[P.stampAe] = asDec(sum('AE'));
  if (P.stampSdr) properties[P.stampSdr] = asDec(sum('SDR'));
  inputs.push({ id: d.dealId, properties });
}
if (!inputs.length) return [{ json: { skip: true, deals: 0 } }];
const out = [];
for (let i = 0; i < inputs.length; i += 100) {
  out.push({ json: { skip: false, url: `${config.hubspot.apiBase}/crm/v3/objects/deals/batch/update`, body: { inputs: inputs.slice(i, i + 100) }, deals: Math.min(100, inputs.length - i) } });
}
return out;

// ============================================================================
// Stamp Result
// ============================================================================
const plan = $('Build Deal Stamp Batches').all().map((i) => i.json);
const exp = $('Export Result').first().json;
if (plan.length === 1 && plan[0].skip) return [{ json: { ...exp, stamp: { attempted: false, stamped: 0, failed: 0, note: 'No deals to stamp' } } }];
const res = $input.all().map((i) => i.json);
let stamped = 0;
let failed = 0;
const errors = [];
res.forEach((r, i) => {
  if (r.error) { failed += plan[i] ? plan[i].deals : 0; errors.push(String(r.error.message || r.error).slice(0, 200)); return; }
  stamped += (r.results || []).length;
  for (const e of r.errors || []) { failed++; errors.push(String(e.message || e.category || 'error').slice(0, 200)); }
});
return [{ json: { ...exp, stamp: { attempted: true, stamped, failed, errors: errors.slice(0, 20) } } }];

// ============================================================================
// Reconciliation Report  (terminal)
// ============================================================================
const { config, safetyDecisions } = $('Config & Safety Gate').first().json;
const calc = $('Clawback Calculator').first().json;
const r = $input.first().json || {};
let status;
if (r.mode === 'dry-run') status = 'DRY_RUN';
else if (r.stamp && r.stamp.failed) status = 'EXPORTED_STAMP_PARTIAL';
else if (r.stamp && r.stamp.attempted) status = 'EXPORTED_AND_STAMPED';
else status = 'EXPORTED';
return [{
  json: {
    status,
    reconciliationId: calc.reconciliationId,
    period: calc.period,
    mode: config.sandboxMode ? 'SANDBOX' : config.dryRun ? 'LIVE / DRY-RUN' : 'LIVE',
    payrollCurrency: calc.payrollCurrency,
    totals: calc.totals,
    dealStatusCounts: calc.statusCounts,
    rowStatusCounts: calc.rowStatusCounts,
    guards: calc.guards,
    pendingReview: calc.deals.filter((d) => d.status === 'PENDING_REVIEW').map((d) => ({ dealId: d.dealId, reasonCode: d.reasonCode })),
    files: r.files || r.draftFiles || [],
    exportBlockedBy: r.exportBlockedBy || [],
    stampBlockedBy: r.mode === 'dry-run' ? r.stampBlockedBy : r.stamp ? [] : config.hubspot.stampBlockers,
    stamp: r.stamp || null,
    safetyDecisions,
    configWarnings: config.warnings,
    collectionWarnings: calc.collectionWarnings,
  },
}];
